/// JS: `canonicalAgents(_input, _context)` — returns the canonical data, verbatim.
pub fn canonicalAgents(_input: &Value, _context: &Value) -> Value {
    CANONICAL_AGENTS.clone()
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    #[test]
    fn canonical_agents_parses_with_the_pressed_shape() {
        let v: &Value = &CANONICAL_AGENTS;
        let a = v.as_array().expect("array");
        assert_eq!(a.len(), 20, "pressed length");
        let mut names: Vec<&str> = a.iter().map(|x| x["name"].as_str().expect("name")).collect();
        let n = names.len();
        names.sort(); names.dedup();
        assert_eq!(names.len(), n, "names unique");
    }

    #[test]
    fn canonicalagents_returns_the_static_verbatim() {
        assert_eq!(canonicalAgents(&Value::Null, &Value::Null), *CANONICAL_AGENTS);
    }

}
